OF = OF or {}
OF.stretch = OF.stretch or {}

local stretch = OF.stretch

stretch.MODEL = "of_stretch_geo"
stretch.TEMPLATE_LIST = "of_stretch_dl"
stretch.TEXTURE_AT = 8
stretch.VERTEX_AT = 13
stretch.LIST_LENGTH = 25
stretch.UV_CELL = 1024
stretch.CELL = 200
stretch.MAX_W = 32
stretch.MAX_H = 16
stretch.MAX_D = 32

stretch.CULL = 2000

stretch.POOL_LISTS = 960
stretch.POOL_BUFFERS = 1024
stretch.VERTEX_COUNT = 24

stretch.KIND_BOX = 0
stretch.KINDS = { [0] = "box" }

stretch.BOX_HALF_UP, stretch.BOX_HALF = 46, 47

function stretch.halves(n)
    if n % 2 == 0 then return n // 2 end
    return n / 2
end
stretch.KINDS[46], stretch.KINDS[47] = "box", "box"
function stretch.is_box(byte) return stretch.KINDS[byte] == "box" end

function stretch.cells_of(byte, w, h, d)
    if byte == stretch.BOX_HALF_UP then return w, stretch.halves(h), d end
    if byte == stretch.BOX_HALF then
        return stretch.halves(w), stretch.halves(h), stretch.halves(d)
    end
    return w, h, d
end

local BLOCK_TEXTURE_LIST = "_draw"
local BLOCK_TEXTURE_AT = 1
local G_SETTIMG = 0xFD

local FACES = {
    { n = { 1, 0, 0 }, r = { 0, 0, -1 }, u = { 0, 1, 0 } },
    { n = { -1, 0, 0 }, r = { 0, 0, 1 }, u = { 0, 1, 0 } },
    { n = { 0, 0, 1 }, r = { 1, 0, 0 }, u = { 0, 1, 0 } },
    { n = { 0, 0, -1 }, r = { -1, 0, 0 }, u = { 0, 1, 0 } },
    { n = { 0, 1, 0 }, r = { 1, 0, 0 }, u = { 0, 0, -1 } },
    { n = { 0, -1, 0 }, r = { 1, 0, 0 }, u = { 0, 0, 1 } },
}
local CORNERS = { { 0, 0 }, { 1, 0 }, { 1, 1 }, { 0, 1 } }

local function axis_of(v)
    for i = 1, 3 do
        if v[i] ~= 0 then return i end
    end
    return 1
end

function stretch.uv_start(n)
    return -(n // 2) * stretch.UV_CELL
end

function stretch.box_vertices(w, h, d)
    local cell = stretch.CELL
    local lo = { -w * cell / 2, 0, -d * cell / 2 }
    local hi = { w * cell / 2, h * cell, d * cell / 2 }
    local size = { w, h, d }
    local out = {}
    for _, face in ipairs(FACES) do
        local an, ar, au = axis_of(face.n), axis_of(face.r), axis_of(face.u)
        for _, corner in ipairs(CORNERS) do
            local cr, cu = corner[1], corner[2]
            local p = { 0, 0, 0 }
            p[an] = face.n[an] > 0 and hi[an] or lo[an]
            p[ar] = ((face.r[ar] > 0) == (cr == 1)) and hi[ar] or lo[ar]
            p[au] = ((face.u[au] > 0) == (cu == 1)) and hi[au] or lo[au]
            table.insert(out, {
                x = p[1], y = p[2], z = p[3],
                tu = cr * size[ar] * stretch.UV_CELL + stretch.uv_start(size[ar]),
                tv = (1 - cu) * size[au] * stretch.UV_CELL + stretch.uv_start(size[au]),
                nx = face.n[1] * 127, ny = face.n[2] * 127, nz = face.n[3] * 127,
            })
        end
    end
    return out
end

local function clamp(n, most)
    n = math.floor(tonumber(n) or 1)
    if n < 1 then return 1 end
    if n > most then return most end
    return n
end

local function as_s32(p)
    p = p & 0xFFFFFFFF
    if p >= 0x80000000 then p = p - 0x100000000 end
    return p
end
stretch.as_s32 = as_s32

function stretch.shape_encode(byte, texture, w, h, d)
    byte = math.floor(tonumber(byte) or 0) % 256
    texture = math.floor(tonumber(texture) or 0) % 1024
    w = clamp(w, stretch.MAX_W) - 1
    h = clamp(h, stretch.MAX_H) - 1
    d = clamp(d, stretch.MAX_D) - 1
    return as_s32((byte << 16) | texture | (w << 10) | ((h & 1) << 15) | (d << 24)
        | ((h >> 1) << 29))
end

function stretch.shape_decode(params)
    params = math.floor(tonumber(params) or 0) & 0xFFFFFFFF
    local byte = (params >> 16) & 0xFF

    if stretch.is_prop ~= nil and stretch.is_prop(byte) then
        local rid = stretch.prop_decode(params)
        local w, h, d = stretch.prop_cells(rid)
        return byte, params & 0x3FF, w, h, d
    end
    return byte, params & 0x3FF, ((params >> 10) & 31) + 1,
        (((params >> 15) & 1) | (((params >> 29) & 7) << 1)) + 1, ((params >> 24) & 31) + 1
end

function stretch.sized(params)
    params = math.floor(tonumber(params) or 0) & 0xFFFFFFFF
    if stretch.JOIN_BYTES[(params >> 16) & 0xFF] ~= nil then return false end

    if stretch.is_prop ~= nil and stretch.is_prop((params >> 16) & 0xFF) then return true end
    return (params & 0xFFFFFC00 & ~0x00FF0000) ~= 0
end

local function texture_of(index)
    if OF.spawner == nil or type(OF.spawner.block_slug) ~= "function" then return nil end
    return OF.spawner.block_slug(index)
end
stretch.texture_of = texture_of

function stretch.texture_index(slug)
    if OF.spawner == nil or type(OF.spawner.block_index) ~= "function" then return nil end
    return OF.spawner.block_index(slug)
end

function stretch.key_of(params)
    local byte, texture, w, h, d = stretch.shape_decode(params)
    local join = stretch.JOIN_BYTES[byte]
    if join ~= nil then
        local _, _, arms, other = stretch.join_decode(params)
        return join.tag .. ":" .. (texture_of(texture) or "template") .. ":" .. arms
            .. ":" .. (texture_of(other) or "-")
    end
    if stretch.is_prop ~= nil and stretch.is_prop(byte) then
        local rid = stretch.prop_decode(params)
        local r = stretch.RECIPES ~= nil and stretch.RECIPES[rid] or nil
        local a, b = stretch.prop_slugs(params)
        return "prop:" .. (r ~= nil and r.key or tostring(rid)) .. ":" .. tostring(a) .. ":"
            .. tostring(b)
    end
    local shape = byte == 0 and "box" or (stretch.SHAPES[byte] and stretch.SHAPES[byte].tag)
        or tostring(byte)
    return shape .. ":" .. (texture_of(texture) or "template") .. ":" .. w .. ":" .. h .. ":" .. d
end

function stretch.cull_for(o, w, h, d)
    if o == nil then return false end
    local cell = stretch.CELL
    local rx, ry, rz = w * cell / 2, h * cell, d * cell / 2
    local far = math.sqrt(rx * rx + ry * ry + rz * rz) > stretch.CULL - 100
    if far and o.header ~= nil and o.header.gfx ~= nil then
        o.header.gfx.skipInViewCheck = true
    end
    return far
end

local slots, listOf = {}, {}

local bslots, bufOf = {}, {}

local highList, highBuffer = 0, 0
local freeLists, freeBuffers = {}, {}
local tick = 0
local template, shapeTemplate = nil, nil

local byObject, objSlot, waiting = {}, {}, {}

local objKey = {}

stretch.overCap = 0
stretch.evicted = 0
stretch.refused = 0

local function list_name(slot) return "of_st_dl_" .. slot end
local function buffer_name(slot) return "of_st_vx_" .. slot end

local function bound(name)
    local fn = _G[name]
    if type(fn) ~= "function" then return nil end
    return fn
end

local function template_list()
    if template ~= nil then return template end
    local find = bound("gfx_get_from_name")
    if find == nil then return nil end
    template = find(stretch.TEMPLATE_LIST)
    return template
end

local function shape_template()
    if shapeTemplate ~= nil then return shapeTemplate end
    local find = bound("gfx_get_from_name")
    if find == nil then return nil end
    shapeTemplate = find(stretch.SHAPE_TEMPLATE)
    return shapeTemplate
end

local NEEDED = { "gfx_get_from_name", "gfx_create", "gfx_copy", "gfx_get_command",
    "gfx_set_command", "vtx_get_from_name", "vtx_create", "vtx_get_next_vertex" }

local function bindings_here()
    for _, name in ipairs(NEEDED) do
        if bound(name) == nil then return false end
    end
    return true
end

local function own_list(slot, length)
    local name = list_name(slot)
    local found, have = gfx_get_from_name(name)
    if found ~= nil then
        if have ~= length and bound("gfx_resize") ~= nil then gfx_resize(found, length) end
        return found
    end
    return gfx_create(name, length)
end

local function own_buffer(slot, count)
    local name = buffer_name(slot)
    local found, have = vtx_get_from_name(name)
    if found ~= nil then
        if have ~= count and bound("vtx_resize") ~= nil then vtx_resize(found, count) end
        return found
    end
    return vtx_create(name, count)
end

local function oldest_idle(records, field)
    local best, bestUsed = nil, nil
    for n, rec in pairs(records) do
        if rec[field] <= 0 and (bestUsed == nil or rec.used < bestUsed) then
            best, bestUsed = n, rec.used
        end
    end
    return best
end

local function forget_buffer(b)
    local rec = bslots[b]
    if rec == nil then return end
    if bufOf[rec.key] == b then bufOf[rec.key] = nil end
end

local function forget_list(n)
    local rec = slots[n]
    if rec == nil then return end
    if listOf[rec.key] == n then listOf[rec.key] = nil end
    local b = rec.buf
    if b ~= nil and bslots[b] ~= nil then
        bslots[b].users = math.max(bslots[b].users - 1, 0)
        bslots[b].used = tick
    end
    rec.buf = nil
end

local function drop_list(n)
    local rec = slots[n]
    if rec == nil then return end
    forget_list(n)
    if bound("gfx_delete") ~= nil and rec.gfx ~= nil then gfx_delete(rec.gfx) end
    slots[n] = nil
    table.insert(freeLists, n)
    stretch.evicted = stretch.evicted + 1
end

local function buffer_slot(key, count, fill)
    tick = tick + 1
    local have = bufOf[key]
    if have ~= nil then
        bslots[have].used = tick
        return have
    end
    local b = table.remove(freeBuffers)
    local vtx = nil
    if b == nil and highBuffer < stretch.POOL_BUFFERS then
        b = highBuffer + 1
        vtx = own_buffer(b, count)
        if vtx ~= nil then highBuffer = b else b = nil end
    elseif b ~= nil then
        vtx = own_buffer(b, count)
        if vtx == nil then
            table.insert(freeBuffers, b)
            b = nil
        end
    end
    if b == nil then
        b = oldest_idle(bslots, "users")

        while b == nil do
            local n = oldest_idle(slots, "refs")
            if n == nil then return nil end
            drop_list(n)
            b = oldest_idle(bslots, "users")
        end
        forget_buffer(b)
        vtx = bslots[b].vtx
        if bound("vtx_resize") ~= nil then vtx_resize(vtx, count) end
        stretch.evicted = stretch.evicted + 1
    end
    local groups = fill(vtx)
    if groups == false then
        bslots[b] = { key = "", vtx = vtx, users = 0, used = 0 }
        return nil
    end
    bslots[b] = { key = key, vtx = vtx, users = 0, used = tick, groups = groups }
    bufOf[key] = b
    return b
end

local function list_slot(params, length, b)
    local n = table.remove(freeLists)
    local gfx = nil
    if n == nil and highList < stretch.POOL_LISTS then
        n = highList + 1
        gfx = own_list(n, length)
        if gfx ~= nil then highList = n else n = nil end
    elseif n ~= nil then
        gfx = own_list(n, length)
        if gfx == nil then
            table.insert(freeLists, n)
            n = nil
        end
    end
    if n == nil then
        n = oldest_idle(slots, "refs")
        if n == nil then return nil end
        forget_list(n)
        gfx = slots[n].gfx
        if bound("gfx_resize") ~= nil then gfx_resize(gfx, length) end
        stretch.evicted = stretch.evicted + 1
    end
    slots[n] = { key = params, gfx = gfx, refs = 0, used = tick, buf = b }
    listOf[params] = n
    if b ~= nil and bslots[b] ~= nil then bslots[b].users = bslots[b].users + 1 end
    return n
end

local function texture_command(slug)
    if slug == nil then return nil end
    local list = gfx_get_from_name("of_blk_" .. slug .. BLOCK_TEXTURE_LIST)
    if list == nil then return nil end
    local cmd = gfx_get_command(list, BLOCK_TEXTURE_AT)
    if cmd == nil or bound("gfx_get_op") == nil or gfx_get_op(cmd) ~= G_SETTIMG then
        return nil
    end
    return cmd
end

local function fill_box(w, h, d)
    return function(vtx)
        local at = vtx
        for _, v in ipairs(stretch.box_vertices(w, h, d)) do
            if at == nil then return false end
            at.x, at.y, at.z = v.x, v.y, v.z
            at.flag = 0
            at.tu, at.tv = v.tu, v.tv
            at.nx, at.ny, at.nz = v.nx, v.ny, v.nz
            at.a = 255
            at = vtx_get_next_vertex(at)
        end
        return true
    end
end

local function build_box(params, texture, w, h, d)
    local source = template_list()
    if source == nil then return nil end
    local b = buffer_slot("0:" .. w .. ":" .. h .. ":" .. d, stretch.VERTEX_COUNT, fill_box(w, h, d))
    if b == nil then return nil, "full" end
    local n = list_slot(params, stretch.LIST_LENGTH, b)
    if n == nil then return nil, "full" end
    local gfx = slots[n].gfx
    gfx_copy(gfx, source, stretch.LIST_LENGTH)
    local tex = texture_command(texture_of(texture))
    if tex ~= nil then
        gfx_copy(gfx_get_command(gfx, stretch.TEXTURE_AT), tex, 1)
    end
    gfx_set_command(gfx_get_command(gfx, stretch.VERTEX_AT), "gsSPVertex(%v, %i, 0)",
        bslots[b].vtx, stretch.VERTEX_COUNT)
    return n
end

