local function side_top(pts, ux, uz, px, pz)
    local at = px * ux + pz * uz
    local best = nil
    for i = 1, #pts do
        local a, b = pts[i], pts[(i % #pts) + 1]
        local sa, sb = a[1] * ux + a[3] * uz, b[1] * ux + b[3] * uz
        local lo, hi = math.min(sa, sb), math.max(sa, sb)
        if at >= lo - 1e-6 and at <= hi + 1e-6 then
            local y
            if math.abs(sb - sa) < 1e-9 then y = math.max(a[2], b[2])
            else y = a[2] + (b[2] - a[2]) * (at - sa) / (sb - sa) end
            if best == nil or y > best then best = y end
        end
    end
    return best or 0
end

local function pack_faces(faces, order)
    local verts, groups = {}, {}
    for _, want in ipairs(order) do
        local chunks, chunk = {}, nil
        for _, f in ipairs(faces) do
            if want == -1 or f.layer == want then
                local n = #f.points
                if chunk == nil or chunk.count + n > stretch.SHAPE_CHUNK then
                    chunk = { start = #verts, count = 0, tris = {} }
                    table.insert(chunks, chunk)
                end
                for _, p in ipairs(f.points) do
                    table.insert(verts, { p[1], p[2], p[3], math.floor(p[4] + 0.5),
                        math.floor(p[5] + 0.5), math.floor(f.nx * 127 + 0.5),
                        math.floor(f.ny * 127 + 0.5), math.floor(f.nz * 127 + 0.5) })

                    if p[6] ~= nil then verts[#verts][12] = p[6] end
                end
                local base = chunk.count
                for k = 1, n - 2 do
                    table.insert(chunk.tris, { base, base + k, base + k + 1 })
                end
                chunk.count = chunk.count + n
            end
        end
        if #chunks > 0 then groups[want] = chunks end
    end
    return { verts = verts, groups = groups }
end

function stretch.shape_geometry(byte, w, h, d, layered)
    local faces = stretch.shape_faces(byte, w, h, d, layered)
    if faces == nil then return nil end
    return pack_faces(faces, layered and { 0, 1, 2 } or { -1 })
end

function stretch.shape_faces(byte, w, h, d, layered)
    local shape = stretch.SHAPES[byte]
    if shape == nil then return nil end
    local one = w == 1 and h == 1 and d == 1
    local cell, U = stretch.CELL, stretch.UV_CELL
    local faces = {}
    for _, f in ipairs(shape.f) do
        local n = (#f - 4) // 7

        local nx, ny, nz = f[2] / w, f[3] / h, f[4] / d
        local len = math.sqrt(nx * nx + ny * ny + nz * nz)
        if len == 0 then len = 1 end
        nx, ny, nz = nx / len, ny / len, nz / len
        local pts = {}
        for k = 0, n - 1 do
            local at = 5 + k * 7
            pts[k + 1] = { f[at] * w, f[at + 1] * h, f[at + 2] * d,
                           f[at + 3], f[at + 4], f[at + 5], f[at + 6] }
        end
        local ux, uz = nz, -nx
        local ulen = math.sqrt(ux * ux + uz * uz)
        local out = { layer = f[1], nx = nx, ny = ny, nz = nz, points = {} }
        for k = 1, n do
            local p = pts[k]
            local tu, tv
            if one then
                tu, tv = layered and p[6] or p[4], layered and p[7] or p[5]
            elseif (nx == 0 and nz == 0) or ny > 0.8 then
                tu = (p[1] + w * cell / 2) / cell * U + stretch.uv_start(w)
                tv = (p[3] + d * cell / 2) / cell * U + stretch.uv_start(d)
            else
                local along = (p[1] * ux + p[3] * uz) / ulen
                local extent = math.abs(ux) > math.abs(uz) and w or d
                tu = (along + extent * cell / 2) / cell * U + stretch.uv_start(extent)
                local top = h * cell
                if layered and ny == 0 then
                    top = side_top(pts, ux / ulen, uz / ulen, p[1], p[3])
                end
                tv = (top - p[2]) / cell * U + stretch.uv_start(h)
            end
            out.points[k] = { p[1], p[2], p[3], tu, tv }
        end
        faces[#faces + 1] = out
    end
    return faces
end

local function fill_geometry(geo)
    return function(vtx)
        local at = vtx
        for _, v in ipairs(geo.verts) do
            if at == nil then return false end
            at.x, at.y, at.z = v[1], v[2], v[3]
            at.flag = 0
            at.tu, at.tv = v[4], v[5]
            if v[9] ~= nil then
                at.r, at.g, at.b = v[9], v[10], v[11]
            else
                at.nx, at.ny, at.nz = v[6], v[7], v[8]
            end
            at.a = 255
            at = vtx_get_next_vertex(at)
        end
        return geo.groups
    end
end

local function layer_load(slug, which)
    local list = gfx_get_from_name("of_blk_" .. slug .. BLOCK_GEOMETRY_LIST)
    if list == nil then return nil end
    local seen = 0
    for i = 1, gfx_get_length(list) - 1 do
        local cmd = gfx_get_command(list, i)
        if cmd ~= nil and gfx_get_op(cmd) == G_SETTIMG then
            seen = seen + 1
            if seen == which then
                local run = gfx_get_command(list, i - 1)
                return function(gfx, at)
                    gfx_copy(gfx_get_command(gfx, at), run, 4)
                    return at + 4
                end
            end
        end
    end
    return nil
end

local function other_load(source, slug)
    local list = slug ~= nil and gfx_get_from_name("of_blk_" .. slug .. BLOCK_TEXTURE_LIST) or nil
    if list == nil then return nil end
    local cmd = gfx_get_command(list, BLOCK_TEXTURE_AT)
    if cmd == nil or gfx_get_op(cmd) ~= G_SETTIMG then return nil end
    return function(gfx, at)
        gfx_copy(gfx_get_command(gfx, at), gfx_get_command(source, 0), 1)
        gfx_copy(gfx_get_command(gfx, at + 1), cmd, 3)
        return at + 4
    end
end

local function write_list(params, source, slug, b, loads, baked)
    local groups = bslots[b].groups
    local length = SHAPE_HEAD + SHAPE_TAIL + (baked and 2 or 0) + stretch.FOG_WORDS
    for layer, chunks in pairs(groups) do
        if layer > 0 and loads[layer] ~= nil then length = length + 4 end
        for _, chunk in ipairs(chunks) do
            length = length + 1 + (#chunk.tris + 1) // 2
        end
    end
    local n = list_slot(params, length, b)
    if n == nil then return nil end
    local gfx = slots[n].gfx
    local vtx = bslots[b].vtx
    gfx_copy(gfx, source, SHAPE_HEAD)
    local tex = texture_command(slug)
    if tex ~= nil then gfx_copy(gfx_get_command(gfx, stretch.TEXTURE_AT), tex, 1) end
    local at = SHAPE_HEAD

    if baked then
        gfx_set_command(gfx_get_command(gfx, at), "gsSPGeometryMode(%i, %i)", stretch.G_LIGHTING, 0)
        at = at + 1
    end

    stretch.fog_mark(slots[n], gfx, at)
    at = at + stretch.FOG_WORDS
    for _, layer in ipairs({ -1, 0, 1, 2 }) do
        local chunks = groups[layer]
        if chunks ~= nil then
            if layer > 0 and loads[layer] ~= nil then at = loads[layer](gfx, at) end
            for _, chunk in ipairs(chunks) do
                gfx_set_command(gfx_get_command(gfx, at), "gsSPVertex(%v, %i, 0)",
                    vtx_get_vertex(vtx, chunk.start), chunk.count)
                at = at + 1
                local tris = chunk.tris
                for k = 1, #tris, 2 do
                    local a, c = tris[k], tris[k + 1]
                    if c ~= nil then
                        gfx_set_command(gfx_get_command(gfx, at),
                            "gsSP2Triangles(%i, %i, %i, %i, %i, %i, %i, %i)",
                            a[1], a[2], a[3], 0, c[1], c[2], c[3], 0)
                    else
                        gfx_set_command(gfx_get_command(gfx, at),
                            "gsSP1Triangle(%i, %i, %i, %i)", a[1], a[2], a[3], 0)
                    end
                    at = at + 1
                end
            end
        end
    end
    if baked then
        gfx_set_command(gfx_get_command(gfx, at), "gsSPGeometryMode(%i, %i)", 0, stretch.G_LIGHTING)
        at = at + 1
    end
    gfx_copy(gfx_get_command(gfx, at), gfx_get_command(source, SHAPE_TAIL_AT), SHAPE_TAIL)
    return n
end

local function build_shape(params, byte, texture, w, h, d)
    local source = shape_template()
    local slug = texture_of(texture)
    if source == nil or slug == nil or stretch.SHAPES[byte] == nil then return nil end
    if bound("gfx_get_op") == nil or bound("gfx_get_length") == nil
        or bound("vtx_get_vertex") == nil then
        return nil
    end
    local layered = OF.spawner.block_layered ~= nil and OF.spawner.block_layered(slug) == true
    local key = byte .. ":" .. w .. ":" .. h .. ":" .. d .. ":" .. (layered and 1 or 0)
    local geo = nil
    if bufOf[key] == nil then
        geo = stretch.shape_geometry(byte, w, h, d, layered)
        if geo == nil or #geo.verts == 0 then return nil end
    end
    local b = buffer_slot(key, geo ~= nil and #geo.verts or 0,
        geo ~= nil and fill_geometry(geo) or function() return false end)
    if b == nil then return nil, "full" end
    local loads = {}
    if layered then
        for k = 1, 2 do loads[k] = layer_load(slug, k) end
    end
    local n = write_list(params, source, slug, b, loads)
    if n == nil then return nil, "full" end
    return n
end

stretch.JOIN_BYTES = {
    [44] = { tag = "pillarjoin", base = "pillar" },
    [45] = { tag = "fencejoin", base = "fence" },
}
stretch.JOIN_PILLAR, stretch.JOIN_FENCE = 44, 45

stretch.PILLAR_BYTE, stretch.FENCE_BYTE = 14, 12

function stretch.join_reach(code)
    local J = stretch.JOIN_SIZES
    if code == 2 then return J.cell / 2 + (J.cell / 2 - J.pillar) end
    if code == 3 then return J.cell / 2 + (J.cell / 2 - J.wall / 2) end
    return J.cell / 2
end

function stretch.join_encode(byte, texture, arms, other)
    byte = math.floor(tonumber(byte) or 0) % 256
    texture = math.floor(tonumber(texture) or 0) % 1024
    local p = (byte << 16) | texture
    if byte == stretch.JOIN_PILLAR then
        local mask = 0
        for k = 1, 4 do
            if (arms[k] or 0) > 0 then mask = mask | (1 << (k - 1)) end
        end
        other = math.floor(tonumber(other) or 0) % 1024
        p = p | (mask << 24) | ((other & 63) << 10) | ((other >> 6) << 28)
    else
        for k = 1, 4 do
            p = p | ((math.floor(arms[k] or 0) & 3) << (24 + 2 * (k - 1)))
        end
    end
    return as_s32(p)
end

function stretch.join_decode(params)
    params = math.floor(tonumber(params) or 0) & 0xFFFFFFFF
    local byte, texture = (params >> 16) & 0xFF, params & 0x3FF
    local codes, other = {}, 0
    if byte == stretch.JOIN_PILLAR then
        local mask = (params >> 24) & 15
        for k = 1, 4 do codes[k] = (mask >> (k - 1)) & 1 end
        other = ((params >> 10) & 63) | (((params >> 28) & 15) << 6)
    else
        for k = 1, 4 do codes[k] = (params >> (24 + 2 * (k - 1))) & 3 end
    end
    return byte, texture, table.concat(codes), other, codes
end

stretch.WALL_ARMS = {
    [10] = { 1, 3 }, [11] = { 3, 4 }, [29] = { 1, 3, 4 }, [30] = { 1, 2, 3, 4 },
    [34] = { 1, 3 }, [35] = { 1, 3 }, [40] = { 1, 3 }, [41] = { 1, 3 },
}
stretch.FENCE_BYTES = { [12] = true, [13] = true }
function stretch.quarter_of(yaw)
    return math.floor(((tonumber(yaw) or 0) % 0x10000) / 0x4000 + 0.5) % 4
end
function stretch.world_side(k, q) return ((k - 1 - q) % 4) + 1 end
function stretch.own_side(k, q) return ((k - 1 + q) % 4) + 1 end
function stretch.across(k) return ((k + 1) % 4) + 1 end

function stretch.wall_reaches(byte, q, k)
    local arms = stretch.WALL_ARMS[byte]
    if arms == nil then return false end
    for _, a in ipairs(arms) do
        if stretch.world_side(a, q) == k then return true end
    end
    return false
end

function stretch.join_codes(kind, q, texture, sides)
    local codes, other, any = { 0, 0, 0, 0 }, 0, false
    for k = 1, 4 do
        local n = sides[k]
        local code = 0
        if n ~= nil then
            local byte = n.byte
            local reaches = stretch.wall_reaches(byte, n.q or 0, stretch.across(k))
            if stretch.WALL_ARMS[byte] ~= nil then
                if kind == "pillar" then
                    if reaches then
                        code = 1
                        if other == 0 then other = n.texture or 0 end
                    end
                elseif reaches then code = 1
                elseif (n.thick or 1) == 1 then code = 3 end
            elseif kind == "fence" then
                if stretch.FENCE_BYTES[byte] or stretch.is_box(byte) then code = 1
                elseif byte == stretch.PILLAR_BYTE then code = 2 end
            end
        end
        if code > 0 then any = true end
        codes[stretch.own_side(k, q)] = code
    end
    if not any then return nil end
    return stretch.join_encode(kind == "pillar" and stretch.JOIN_PILLAR or stretch.JOIN_FENCE,
        texture, codes, other ~= texture and other or 0)
end

function stretch.wall_thick(params)
    local byte, _, _, _, d = stretch.shape_decode(params)
    if stretch.WALL_ARMS[byte] == nil then return 1 end
    return d
end

function stretch.resolve_joins(spots)
    local cell = stretch.CELL
    local at, laid = {}, {}

    for _, s in ipairs(spots) do laid[s] = s.params end
    local function key(x, y, z)
        return math.floor(x / cell + 0.5) .. ":" .. math.floor(y / cell + 0.5) .. ":"
            .. math.floor(z / cell + 0.5)
    end
    for _, s in ipairs(spots) do
        local byte, _, w, h, d = stretch.shape_decode(s.params)
        if stretch.JOIN_BYTES[byte] ~= nil then w, h, d = 1, 1, 1 end
        w, h, d = stretch.cells_of(byte, w, h, d)
        local q = stretch.quarter_of(s.yaw)
        local ex, ez = w, d
        if q % 2 == 1 then ex, ez = d, w end
        for i = 0, math.max(math.ceil(ex) - 1, 0) do
            for j = 0, math.max(math.ceil(h) - 1, 0) do
                for k = 0, math.max(math.ceil(ez) - 1, 0) do
                    local x = s.x - ex * cell / 2 + (i + 0.5) * cell
                    local z = s.z - ez * cell / 2 + (k + 0.5) * cell
                    at[key(x, s.y + j * cell, z)] = s
                end
            end
        end
    end
    local joined = 0
    local dx, dz = { 1, 0, -1, 0 }, { 0, 1, 0, -1 }
    for _, s in ipairs(spots) do
        local byte, texture = stretch.shape_decode(s.params)
        local kind = (byte == stretch.PILLAR_BYTE and "pillar")
            or (stretch.FENCE_BYTES[byte] and "fence") or nil
        if kind ~= nil and not stretch.sized(s.params) then
            local sides = {}
            for k = 1, 4 do
                local n = at[key(s.x + dx[k] * cell, s.y, s.z + dz[k] * cell)]
                if n ~= nil and n ~= s then
                    local nb, nt = stretch.shape_decode(laid[n])
                    sides[k] = { byte = nb, q = stretch.quarter_of(n.yaw), texture = nt,
                                 thick = stretch.wall_thick(laid[n]) }
                end
            end
            local word = stretch.join_codes(kind, stretch.quarter_of(s.yaw), texture, sides)
            if word ~= nil then
                s.params = word
                joined = joined + 1
            end
        end
    end
    return joined
end

local function box_faces(x0, x1, y0, y1, z0, z1, layer)
    local J = stretch.JOIN_SIZES
    local full, lo, cell, top = stretch.SHAPE_UV_FULL, -J.cell / 2, J.cell, J.top
    local function uv(p, nx, ny, nz)
        if nx == 0 and nz == 0 then
            return (p[1] - lo) / cell * full, (p[3] - lo) / cell * full
        end
        return ((p[1] * nz - p[3] * nx) - lo) / cell * full, (top - p[2]) / top * full
    end
    local quads = {
        { { x0, y1, z0 }, { x0, y1, z1 }, { x1, y1, z1 }, { x1, y1, z0 }, 0, 1, 0 },
        { { x0, y0, z0 }, { x1, y0, z0 }, { x1, y0, z1 }, { x0, y0, z1 }, 0, -1, 0 },
        { { x0, y0, z0 }, { x0, y1, z0 }, { x1, y1, z0 }, { x1, y0, z0 }, 0, 0, -1 },
        { { x0, y0, z1 }, { x1, y0, z1 }, { x1, y1, z1 }, { x0, y1, z1 }, 0, 0, 1 },
        { { x0, y0, z0 }, { x0, y0, z1 }, { x0, y1, z1 }, { x0, y1, z0 }, -1, 0, 0 },
        { { x1, y0, z0 }, { x1, y1, z0 }, { x1, y1, z1 }, { x1, y0, z1 }, 1, 0, 0 },
    }
    local out = {}
    for _, q in ipairs(quads) do
        local nx, ny, nz = q[5], q[6], q[7]
        local face = { layer = layer, nx = nx, ny = ny, nz = nz, points = {} }
        for k = 1, 4 do
            local s, t = uv(q[k], nx, ny, nz)
            face.points[k] = { q[k][1], q[k][2], q[k][3], s, t }
        end
        out[#out + 1] = face
    end
    return out
end
stretch.box_faces = box_faces

local function arm_box(k, from, to, half, y0, y1, layer)
    if k == 1 then return box_faces(from, to, y0, y1, -half, half, layer) end
    if k == 3 then return box_faces(-to, -from, y0, y1, -half, half, layer) end
    if k == 2 then return box_faces(-half, half, y0, y1, from, to, layer) end
    return box_faces(-half, half, y0, y1, -to, -from, layer)
end
stretch.arm_box = arm_box

function stretch.join_faces(byte, codes, split)
    local J = stretch.JOIN_SIZES
    local faces = {}
    if byte == stretch.JOIN_PILLAR then
        local shaft = stretch.SHAPES[stretch.PILLAR_BYTE]
        for _, f in ipairs(shaft.f) do
            local n = (#f - 4) // 7
            local face = { layer = 0, nx = f[2], ny = f[3], nz = f[4], points = {} }
            local len = math.sqrt(f[2] * f[2] + f[3] * f[3] + f[4] * f[4])
            face.nx, face.ny, face.nz = f[2] / len, f[3] / len, f[4] / len
            for k = 0, n - 1 do
                local at = 5 + k * 7
                face.points[k + 1] = { f[at], f[at + 1], f[at + 2], f[at + 3], f[at + 4] }
            end
            faces[#faces + 1] = face
        end

        local from = J.pillar
        for k = 1, 4 do
            if (codes[k] or 0) > 0 then
                for _, f in ipairs(arm_box(k, from, stretch.join_reach(1), J.wall / 2, 0, J.top,
                    split and 1 or 0)) do
                    faces[#faces + 1] = f
                end
            end
        end
        return faces
    end
    local post = J.fence / 2
    for _, f in ipairs(box_faces(-post, post, 0, J.fence_high, -post, post, 0)) do
        faces[#faces + 1] = f
    end
    for k = 1, 4 do
        local code = codes[k] or 0
        if code > 0 then
            for _, rail in ipairs(J.rails) do
                for _, f in ipairs(arm_box(k, post, stretch.join_reach(code), J.rail, rail[1],
                    rail[2], 0)) do
                    faces[#faces + 1] = f
                end
            end
        end
    end
    return faces
end

local function build_join(params, byte, texture, listKey, turn)
    local source = shape_template()
    local slug = texture_of(texture)
    if source == nil or slug == nil or stretch.JOIN_SIZES == nil then return nil end
    if bound("gfx_get_op") == nil or bound("vtx_get_vertex") == nil then return nil end
    local _, _, arms, other, codes = stretch.join_decode(params)
    local otherSlug = other > 0 and other ~= texture and texture_of(other) or nil
    local split = otherSlug ~= nil
    local key = "j" .. byte .. ":" .. arms .. ":" .. (split and 1 or 0)
        .. (turn ~= nil and (":" .. turn .. ":" .. stretch.bakeSerial) or "")
    local geo = nil
    if bufOf[key] == nil then
        geo = pack_faces(stretch.join_faces(byte, codes, split), split and { 0, 1 } or { -1 })
        stretch.bake_turned(geo, turn)
    end
    local b = buffer_slot(key, geo ~= nil and #geo.verts or 0,
        geo ~= nil and fill_geometry(geo) or function() return false end)
    if b == nil then return nil, "full" end
    stretch.keep_baked(b, geo, turn ~= nil)
    local loads = {}
    if split then loads[1] = other_load(source, otherSlug) end
    local n = write_list(listKey or params, source, slug, b, loads, turn ~= nil)
    if n == nil then return nil, "full" end
    return n
end

stretch.PROP_BANKS = 8
function stretch.is_prop(byte)
    return byte ~= nil and stretch.PROP_BYTE ~= nil and byte >= stretch.PROP_BYTE
        and byte < stretch.PROP_BYTE + stretch.PROP_BANKS
end

function stretch.prop_encode(rid, a, b)
    rid = math.floor(tonumber(rid) or 0) % (16 * stretch.PROP_BANKS)
    a = math.floor(tonumber(a) or 0) % 1024
    b = math.floor(tonumber(b) or 0) % 1024
    local byte = stretch.PROP_BYTE + rid // 16
    return as_s32((byte << 16) | a | ((rid % 16) << 24) | ((b & 63) << 10) | ((b >> 6) << 28))
end

function stretch.prop_decode(params)
    params = math.floor(tonumber(params) or 0) & 0xFFFFFFFF
    local byte = (params >> 16) & 0xFF
    if not stretch.is_prop(byte) then return nil end
    local rid = (byte - stretch.PROP_BYTE) * 16 + ((params >> 24) & 15)
    return rid, params & 0x3FF, ((params >> 10) & 63) | (((params >> 28) & 15) << 6)
end

function stretch.prop_cells(rid)
    local r = stretch.RECIPES ~= nil and stretch.RECIPES[rid] or nil
    local s = r ~= nil and r.solid or nil
    if s == nil then return 1, 1, 1 end
    local cell = stretch.CELL
    return math.max(1, math.ceil(s[1] / cell)), math.max(1, math.ceil(s[2] / cell)),
        math.max(1, math.ceil(s[3] / cell))
end

local shapeBox = {}
local function shape_extent(byte)
    local have = shapeBox[byte]
    if have ~= nil then return have end
    local shape = stretch.SHAPES[byte]
    if shape == nil then return nil end
    local b = { 1e9, -1e9, 1e9, -1e9, 1e9, -1e9 }
    for _, f in ipairs(shape.f) do
        local n = (#f - 4) // 7
        for k = 0, n - 1 do
            local at = 5 + k * 7
            local x, y, z = f[at], f[at + 1], f[at + 2]
            b[1], b[2] = math.min(b[1], x), math.max(b[2], x)
            b[3], b[4] = math.min(b[3], y), math.max(b[4], y)
            b[5], b[6] = math.min(b[5], z), math.max(b[6], z)
        end
    end
    shapeBox[byte] = b
    return b
end

local function prop_uv(x, y, z, nx, ny, nz)
    local full, lo, cell, top = stretch.SHAPE_UV_FULL, -stretch.CELL / 2, stretch.CELL, stretch.CELL
    if math.abs(ny) > 0.7 then
        return (x - lo) / cell * full, (z - lo) / cell * full
    end
    local l = math.sqrt(nx * nx + nz * nz)
    if l == 0 then l = 1 end
    return ((x * nz - z * nx) / l - lo) / cell * full, (top - y) / top * full
end

local function part_faces(byte, x0, x1, y0, y1, z0, z1, layer, q)
    if byte == 0 then return box_faces(x0, x1, y0, y1, z0, z1, layer) end
    local shape = stretch.SHAPES[byte]
    local ext = shape_extent(byte)
    if shape == nil or ext == nil then return box_faces(x0, x1, y0, y1, z0, z1, layer) end
    local function turn(x, z)
        for _ = 1, q % 4 do x, z = z, -x end
        return x, z
    end

    local ax0, az0 = turn(ext[1], ext[5])
    local ax1, az1 = turn(ext[2], ext[6])
    local ux0, ux1 = math.min(ax0, ax1), math.max(ax0, ax1)
    local uz0, uz1 = math.min(az0, az1), math.max(az0, az1)
    local sx = (x1 - x0) / math.max(ux1 - ux0, 1)
    local sy = (y1 - y0) / math.max(ext[4] - ext[3], 1)
    local sz = (z1 - z0) / math.max(uz1 - uz0, 1)
    local out = {}
    for _, f in ipairs(shape.f) do
        local n = (#f - 4) // 7
        local nx, nz = turn(f[2], f[4])
        local ny = f[3]
        nx, ny, nz = nx / sx, ny / sy, nz / sz
        local len = math.sqrt(nx * nx + ny * ny + nz * nz)
        if len == 0 then len = 1 end
        nx, ny, nz = nx / len, ny / len, nz / len
        local face = { layer = layer, nx = nx, ny = ny, nz = nz, points = {} }
        for k = 0, n - 1 do
            local at = 5 + k * 7
            local px, pz = turn(f[at], f[at + 2])
            local wx = x0 + (px - ux0) * sx
            local wy = y0 + (f[at + 1] - ext[3]) * sy
            local wz = z0 + (pz - uz0) * sz
            local s, t = prop_uv(wx, wy, wz, nx, ny, nz)
            face.points[k + 1] = { wx, wy, wz, s, t }
        end
        out[#out + 1] = face
    end
    return out
end

function stretch.prop_faces(rid)
    local r = stretch.RECIPES ~= nil and stretch.RECIPES[rid] or nil
    if r == nil then return nil end
    local faces = {}
    for _, p in ipairs(r.parts) do
        for _, f in ipairs(part_faces(p[1], p[2], p[3], p[4], p[5], p[6], p[7], p[8], p[9])) do
            faces[#faces + 1] = f
        end
    end
    return faces
end

function stretch.prop_slugs(params)
    local rid, a, b = stretch.prop_decode(params)
    local r = rid ~= nil and stretch.RECIPES ~= nil and stretch.RECIPES[rid] or nil
    if r == nil then return nil end
    local mats = r.mats or {}
    local sa = (a > 0 and texture_of(a)) or mats.a
    local sb = (b > 0 and texture_of(b)) or mats.b
    return sa or sb or mats.c, sb, mats.c
end

local function build_prop(params, listKey, turn)
    local source = shape_template()
    local rid = stretch.prop_decode(params)
    if source == nil or rid == nil or stretch.RECIPES == nil or stretch.RECIPES[rid] == nil then
        return nil
    end
    if bound("gfx_get_op") == nil or bound("vtx_get_vertex") == nil then return nil end
    local sa, sb, sc = stretch.prop_slugs(params)
    local key = "p" .. rid .. (turn ~= nil and (":" .. turn .. ":" .. stretch.bakeSerial) or "")
    local geo = nil
    if bufOf[key] == nil then
        geo = pack_faces(stretch.prop_faces(rid), { 0, 1, 2 })
        if geo == nil or #geo.verts == 0 then return nil end
        stretch.bake_turned(geo, turn)
    end
    local b = buffer_slot(key, geo ~= nil and #geo.verts or 0,
        geo ~= nil and fill_geometry(geo) or function() return false end)
    if b == nil then return nil, "full" end
    stretch.keep_baked(b, geo, turn ~= nil)

    local loads = {}
    loads[1] = other_load(source, sb or sa)
    loads[2] = other_load(source, sc or sa)
    local n = write_list(listKey or params, source, sa, b, loads, turn ~= nil)
    if n == nil then return nil, "full" end
    return n
end
stretch.build_prop = build_prop

stretch.MERGED_BYTE = 240
stretch.G_LIGHTING = 0x00020000
stretch.bake = nil
stretch.relit = nil

stretch.FOG_WORDS = 3
stretch.G_FOG = 0x00010000

stretch.FOG_SHADE_A = 0xC8000000
stretch.FOG_CYCLE1 = 0xCCC00000
stretch.PLAIN_CYCLE1 = 0x00400000
stretch.fogOn = false

local function fog_words(rec)
    local gfx, at = rec.gfx, rec.fogAt
    if gfx == nil or at == nil then return end
    if stretch.fogOn then
        gfx_set_command(gfx_get_command(gfx, at), "gsSPGeometryMode(%i, %i)", 0, stretch.G_FOG)

        local mul, off = 3200, -2944
        if OF.util.asks(OF.modifiers, "fog_words") then mul, off = OF.modifiers.fog_words() end
        gfx_set_command(gfx_get_command(gfx, at + 1), "gsSPFogFactor(%i, %i)", mul, off)
        gfx_set_command(gfx_get_command(gfx, at + 2), "gsDPSetFogColor(%i, %i, %i, %i)",
            255, 255, 255, 255)
    else
        for k = 0, stretch.FOG_WORDS - 1 do
            gfx_set_command(gfx_get_command(gfx, at + k), "gsDPPipeSync()")
        end
    end
    for _, m in ipairs(rec.fogModes or {}) do
        local data = m[4]
        if stretch.fogOn then data = (data & ~stretch.FOG_CYCLE1) | stretch.FOG_SHADE_A end
        gfx_set_command(gfx_get_command(gfx, m[1]), "gsSPSetOtherMode(%i, %i, %i, %i)",
            0xE2, m[2], m[3], data)
    end
end

function stretch.fog_mark(rec, gfx, at)
    if rec == nil then return end
    rec.fogAt = at
    rec.fogModes = {}
    for i = 0, SHAPE_HEAD - 1 do
        local cmd = gfx_get_command(gfx, i)
        if cmd ~= nil and gfx_get_op(cmd) == 0xE2 then
            local w0, w1 = cmd.w0 or 0, cmd.w1 or 0
            local len = (w0 & 0xFF) + 1
            local sft = 32 - len - ((w0 >> 8) & 0xFF)
            if sft <= 18 and sft + len >= 32 then
                local data = w1 & 0xFFFFFFFF
                if (data & stretch.FOG_CYCLE1) == stretch.FOG_SHADE_A then
                    data = (data & ~stretch.FOG_CYCLE1) | stretch.PLAIN_CYCLE1
                end
                rec.fogModes[#rec.fogModes + 1] = { i, sft, len, data }
            end
        end
    end
    fog_words(rec)
end

function stretch.fog_refresh()
    if not stretch.fogOn then return 0 end
    local done = 0
    for n = 1, highList do
        local rec = slots[n]
        if rec ~= nil and rec.fogAt ~= nil then
            fog_words(rec)
            done = done + 1
        end
    end
    return done
end

function stretch.fog(on)
    on = on == true
    if on == stretch.fogOn then return 0 end
    stretch.fogOn = on
    local done = 0
    for n = 1, highList do
        local rec = slots[n]
        if rec ~= nil and rec.fogAt ~= nil then
            fog_words(rec)
            done = done + 1
        end
    end
    return done
end

stretch.bake_dir = nil
stretch.bakeSerial = 0
stretch.BAKE_TURNS = 16

function stretch.list_key(params, o)
    if stretch.bake_dir == nil or o == nil or type(params) ~= "number" then return params, nil end
    local byte = stretch.shape_decode(params)
    if not (stretch.is_prop(byte) or stretch.JOIN_BYTES[byte] ~= nil) then return params, nil end
    local turn = math.floor((tonumber(o.oFaceAngleYaw) or 0) * stretch.BAKE_TURNS / 65536 + 0.5)
        % stretch.BAKE_TURNS
    return params .. ":" .. turn .. ":" .. stretch.bakeSerial, turn
end

function stretch.bake_turned(geo, turn)
    if turn == nil or geo == nil or type(stretch.bake_dir) ~= "function" then return end
    local a = turn * 2 * math.pi / stretch.BAKE_TURNS
    local c, s = math.cos(a), math.sin(a)
    for _, v in ipairs(geo.verts) do
        local nx, nz = v[6] * c + v[8] * s, -v[6] * s + v[8] * c
        v[6], v[8] = nx, nz
        v[9], v[10], v[11] = stretch.bake_dir(nx, v[7], nz)
        v[13], v[14] = 1.0, 1.0
    end
end

function stretch.keep_baked(b, geo, baked)
    if not baked or geo == nil or bslots[b] == nil then return end
    bslots[b].baked = geo.verts
    bslots[b].sunAt = stretch.sun == nil and stretch.sunSerial or -1
end

stretch.sun = nil
stretch.sunSerial = 0
stretch.RELIGHT_VERTICES = 7200
stretch.RELIGHT_MOVE = 0.03

function stretch.relight(dir)
    local want = nil
    if type(dir) == "table" then
        want = { tonumber(dir[1]) or 0, tonumber(dir[2]) or 0, tonumber(dir[3]) or 0 }
    end
    local have = stretch.sun
    if want == nil and have == nil then return false end
    if want ~= nil and have ~= nil and math.abs(want[1] - have[1]) < stretch.RELIGHT_MOVE
        and math.abs(want[2] - have[2]) < stretch.RELIGHT_MOVE
        and math.abs(want[3] - have[3]) < stretch.RELIGHT_MOVE then
        return false
    end
    stretch.sun = want
    stretch.sunSerial = stretch.sunSerial + 1
    return true
end

function stretch.face_extent(points)
    local most = 0
    for i = 1, #points do
        for j = i + 1, #points do
            local a, b = points[i], points[j]
            local d = math.sqrt((a[1] - b[1]) ^ 2 + (a[2] - b[2]) ^ 2 + (a[3] - b[3]) ^ 2)
            if d > most then most = d end
        end
    end
    return most
end
stretch.MERGED_VERTICES = 3600
stretch.MERGED_REACH = 32000

local merged = {}
local mergedSerial = 0

local mergedCount = {}

function stretch.is_merged(params)
    if type(params) ~= "number" then return false end
    return stretch.shape_decode(params) == stretch.MERGED_BYTE
end

stretch.TOP_SPLIT = 8
stretch.TOP_SPLITS = 4

function stretch.top_splits(byte, w, d)
    if byte ~= 0 then return 1, 1 end
    local a = math.min(stretch.TOP_SPLITS, math.max(1, math.ceil(w / stretch.TOP_SPLIT)))
    local b = math.min(stretch.TOP_SPLITS, math.max(1, math.ceil(d / stretch.TOP_SPLIT)))
    return a, b
end

local function split_quad(points, a, b)
    local function at(s, t)
        local out = {}
        for k = 1, 5 do
            local v = (1 - s) * (1 - t) * points[1][k] + s * (1 - t) * points[2][k]
                + s * t * points[3][k] + (1 - s) * t * points[4][k]
            out[k] = math.floor(v + 0.5)
        end
        return out
    end
    local quads = {}
    for i = 0, a - 1 do
        for j = 0, b - 1 do
            local s0, s1, t0, t1 = i / a, (i + 1) / a, j / b, (j + 1) / b
            quads[#quads + 1] = { at(s0, t0), at(s1, t0), at(s1, t1), at(s0, t1) }
        end
    end
    return quads
end

local function piece_faces(byte, w, h, d, layered)
    if stretch.is_box(byte) then
        local cw, ch, cd = stretch.cells_of(byte, w, h, d)
        local verts = stretch.box_vertices(cw, ch, cd)
        local faces = {}
        local sa, sb = stretch.top_splits(byte, cw, cd)
        for k = 1, #verts, 4 do
            local v = verts[k]
            local points = {}
            for j = 0, 3 do
                local p = verts[k + j]
                points[j + 1] = { p.x, p.y, p.z, p.tu, p.tv }
            end
            local layer = -1
            if layered then
                layer = (v.ny > 63 and 0) or (v.ny < -63 and 2) or 1
            end

            local parts = { points }
            if v.ny > 63 and sa * sb > 1 then
                local alongX = points[1][1] ~= points[2][1]
                parts = split_quad(points, alongX and sa or sb, alongX and sb or sa)
            end
            for _, part in ipairs(parts) do
                faces[#faces + 1] = { layer = layer, nx = v.nx / 127, ny = v.ny / 127,
                                      nz = v.nz / 127, points = part }
            end
        end
        return faces
    end
    return stretch.shape_faces(byte, w, h, d, layered)
end

stretch.piece_faces = piece_faces

local function piece_count(byte, w, h, d, layered)
    if stretch.is_box(byte) then
        local cw, _, cd = stretch.cells_of(byte, w, h, d)
        local sa, sb = stretch.top_splits(byte, cw, cd)
        return stretch.VERTEX_COUNT + 4 * (sa * sb - 1)
    end
    local key = byte .. ":" .. w .. ":" .. h .. ":" .. d .. ":" .. (layered and 1 or 0)
    local n = mergedCount[key]
    if n ~= nil then return n end
    local faces = stretch.shape_faces(byte, w, h, d, layered)
    if faces == nil then return nil end
    n = 0
    for _, f in ipairs(faces) do n = n + #f.points end
    mergedCount[key] = n
    return n
end

local function piece_reach(byte, w, h, d)
    local cw, ch, cd = stretch.cells_of(byte, w, h, d)
    local cell = stretch.CELL
    return math.sqrt((cw * cell / 2) ^ 2 + (cd * cell / 2) ^ 2), ch * cell
end

local function merged_key()
    for _ = 1, 0x10000 do
        mergedSerial = (mergedSerial % 0xFFFF) + 1
        local params = stretch.MERGED_BYTE * 0x10000 + mergedSerial
        local n = listOf[params]
        if n == nil or slots[n] == nil or slots[n].refs <= 0 then
            stretch.merge_forget(params)
            return params
        end
    end
    return nil
end

function stretch.merge_plan(rows)
    local groups, refused, open = {}, {}, {}
    for i, r in ipairs(rows) do
        local byte, texture, w, h, d = r[1], r[2], r[3], r[4], r[5]
        local x, y, z, yaw = r[6], r[7], r[8], tonumber(r[9]) or 0
        local slug = texture_of(texture)
        local quarter = yaw % 90 == 0
        local box = stretch.is_box(byte)

        local layered = slug ~= nil and OF.spawner ~= nil
            and type(OF.spawner.block_layered) == "function"
            and OF.spawner.block_layered(slug) == true or false
        local count = (quarter and slug ~= nil and byte ~= stretch.MERGED_BYTE
            and stretch.JOIN_BYTES[byte] == nil and not stretch.is_prop(byte))
            and piece_count(byte, w, h, d, layered) or nil
        local across, up = piece_reach(byte, w, h, d)
        local far = math.abs(x) + across > stretch.MERGED_REACH
            or math.abs(z) + across > stretch.MERGED_REACH
            or math.abs(y) > stretch.MERGED_REACH or math.abs(y + up) > stretch.MERGED_REACH
        if count == nil or far then
            refused[#refused + 1] = i
        else
            local name = ((box and not layered) and "b:" or "s:") .. texture
            local g = open[name]
            if g == nil or g.count + count > stretch.MERGED_VERTICES then
                local params = merged_key()
                if params == nil then
                    refused[#refused + 1] = i
                    g = nil
                else
                    g = { params = params, rows = {}, count = 0 }
                    merged[params] = { box = box and not layered, texture = texture,
                                       layered = layered, pieces = {} }
                    groups[#groups + 1] = g
                    open[name] = g
                end
            end
            if g ~= nil then
                g.count = g.count + count
                g.rows[#g.rows + 1] = i
                local q = math.floor(yaw / 90 + 0.5) % 4
                table.insert(merged[g.params].pieces, { byte, w, h, d, x, y, z, q })
            end
        end
    end
    return groups, refused
end

function stretch.merge_forget(params)
    merged[params] = nil
    local n = listOf[params]
    if n ~= nil and slots[n] ~= nil and slots[n].refs <= 0 then drop_list(n) end
    local b = bufOf["m:" .. tostring(params)]
    if b ~= nil and bslots[b] ~= nil and bslots[b].users <= 0 then forget_buffer(b) end
end

function stretch.merged_spec(params)
    return merged[params]
end

local function build_merged(params)
    local spec = merged[params]
    if spec == nil then return nil end
    local source = spec.box and template_list() or shape_template()
    local slug = texture_of(spec.texture)
    if source == nil or slug == nil then return nil end
    if bound("gfx_get_op") == nil or bound("gfx_get_length") == nil
        or bound("vtx_get_vertex") == nil then
        return nil
    end
    local key = "m:" .. tostring(params)
    local geo = nil
    if bufOf[key] == nil then
        local faces = {}
        local C = { 1, 0, -1, 0 }
        local S = { 0, 1, 0, -1 }
        for _, p in ipairs(spec.pieces) do
            local own = piece_faces(p[1], p[2], p[3], p[4], spec.layered)
            local c, s = C[p[8] + 1], S[p[8] + 1]
            for _, f in ipairs(own or {}) do
                local points = {}
                for k, pt in ipairs(f.points) do
                    points[k] = { p[5] + pt[1] * c + pt[3] * s, p[6] + pt[2],
                                  p[7] - pt[1] * s + pt[3] * c, pt[4], pt[5] }
                end
                if type(stretch.bake) == "function" then
                    local extent = stretch.face_extent(points)
                    for _, q in ipairs(points) do q[6] = extent end
                end
                faces[#faces + 1] = { layer = f.layer, nx = f.nx * c + f.nz * s, ny = f.ny,
                                      nz = -f.nx * s + f.nz * c, points = points }
            end
        end
        geo = pack_faces(faces, (spec.layered and not spec.box) and { 0, 1, 2 } or { -1 })
        if #geo.verts == 0 then return nil end
        for _, v in ipairs(geo.verts) do
            v[1], v[2], v[3] = math.floor(v[1] + 0.5), math.floor(v[2] + 0.5),
                math.floor(v[3] + 0.5)
        end

        if type(stretch.bake) == "function" then
            spec.baked = true
            for _, v in ipairs(geo.verts) do
                v[9], v[10], v[11], v[13], v[14] =
                    stretch.bake(v[1], v[2], v[3], v[6], v[7], v[8], v[12])
            end
        end
    end
    local b = buffer_slot(key, geo ~= nil and #geo.verts or 0,
        geo ~= nil and fill_geometry(geo) or function() return false end)
    if b == nil then return nil, "full" end

    if geo ~= nil and spec.baked and bslots[b] ~= nil then
        bslots[b].baked = geo.verts
        bslots[b].sunAt = stretch.sun == nil and stretch.sunSerial or -1
    end
    local loads = {}
    if spec.layered and not spec.box then
        for k = 1, 2 do loads[k] = layer_load(slug, k) end
    end
    local n = write_list(params, source, slug, b, loads, spec.baked)
    if n == nil then return nil, "full" end
    return n
end

local function slot_for(params, o)
    local key, turn = stretch.list_key(params, o)
    local have = listOf[key]
    if have ~= nil then return have end
    if not bindings_here() then
        stretch.refused = stretch.refused + 1
        return nil
    end
    tick = tick + 1
    local byte, texture, w, h, d = stretch.shape_decode(params)
    local n, why
    if byte == stretch.MERGED_BYTE then
        n, why = build_merged(params)
    elseif stretch.is_prop(byte) then
        n, why = build_prop(params, key, turn)
    elseif byte == 0 then
        n, why = build_box(params, texture, w, h, d)
    elseif byte == stretch.BOX_HALF_UP then
        n, why = build_box(params, texture, w, stretch.halves(h), d)
    elseif byte == stretch.BOX_HALF then
        n, why = build_box(params, texture, stretch.halves(w), stretch.halves(h), stretch.halves(d))
    elseif stretch.JOIN_BYTES[byte] ~= nil then
        n, why = build_join(params, byte, texture, key, turn)
    else
        n, why = build_shape(params, byte, texture, w, h, d)
    end
    if n == nil then
        if why == "full" then stretch.overCap = stretch.overCap + 1
        else stretch.refused = stretch.refused + 1 end
        return nil
    end
    stretch.lastKey = params
    return n
end

function stretch.list_for(params)
    local n = slot_for(params)
    return n ~= nil and slots[n].gfx or nil
end

stretch.shape_list_for = stretch.list_for

local function attach(o, fallback)
    local params = o.oBehParams
    objKey[o] = params
    local n = slot_for(params, o)
    if n == nil then
        waiting[o] = true
        byObject[o] = fallback
        return fallback
    end
    local rec = slots[n]
    rec.refs = rec.refs + 1
    objSlot[o] = n
    byObject[o] = rec.gfx
    return rec.gfx
end

function stretch.pin(o)
    if o == nil then return false end
    if objSlot[o] ~= nil and objKey[o] == o.oBehParams then return true end
    if objSlot[o] ~= nil or byObject[o] ~= nil then stretch.release(o) end
    attach(o, nil)
    return objSlot[o] ~= nil
end

function stretch.release(o)
    if o == nil then return end
    local n = objSlot[o]
    objSlot[o] = nil
    byObject[o] = nil
    waiting[o] = nil
    objKey[o] = nil
    if n ~= nil and slots[n] ~= nil then
        tick = tick + 1
        local rec = slots[n]
        rec.refs = math.max(rec.refs - 1, 0)
        rec.used = tick
        if rec.refs == 0 and next(waiting) ~= nil then
            for w in pairs(waiting) do byObject[w] = nil end
            waiting = {}
        end
    end
end

function stretch.refresh(o)
    stretch.release(o)
end

local lastNode, display = nil, nil
local shapeNode, shapeDisplay = nil, nil

function geo_stretch(node, _)
    local o = geo_get_current_object()
    if o == nil then return end
    local gfx = byObject[o]
    if gfx ~= nil and objKey[o] ~= o.oBehParams then
        stretch.release(o)
        gfx = nil
    end
    if gfx == nil then
        gfx = attach(o, template_list())
        if gfx == nil then return end
    end
    if node ~= lastNode then
        display = cast_graph_node(node.next)
        lastNode = node
    end
    if display == nil then return end
    display.displayList = gfx
end

function geo_shape(node, _)
    local o = geo_get_current_object()
    if o == nil then return end
    local gfx = byObject[o]
    if gfx ~= nil and objKey[o] ~= o.oBehParams then
        stretch.release(o)
        gfx = nil
    end
    if gfx == nil then

        local merging = stretch.is_merged(o.oBehParams)
        gfx = attach(o, not merging and shape_template() or nil)
        if gfx == nil then
            if merging and o.header ~= nil and o.header.gfx ~= nil then
                local flags = o.header.gfx.node.flags
                o.header.gfx.node.flags = OF.util.add_flag(flags, GRAPH_RENDER_INVISIBLE or 0x10)
            end
            return
        end
    end
    if node ~= shapeNode then
        shapeDisplay = cast_graph_node(node.next)
        shapeNode = node
    end
    if shapeDisplay == nil then return end
    shapeDisplay.displayList = gfx
end

local function count_named(find, name_of, cap)
    if find == nil then return 0 end
    local held = 0
    for slot = 1, cap do
        if find(name_of(slot)) ~= nil then held = held + 1 end
    end
    return held
end

function stretch.pool_counts()
    return count_named(bound("gfx_get_from_name"), list_name, stretch.POOL_LISTS),
        count_named(bound("vtx_get_from_name"), buffer_name, stretch.POOL_BUFFERS)
end
stretch.shape_pool_counts = stretch.pool_counts

function stretch.cache_counts()
    local keys, sizes = 0, 0
    for _ in pairs(listOf) do keys = keys + 1 end
    for _ in pairs(bufOf) do sizes = sizes + 1 end
    return keys, sizes
end
stretch.shape_cache_counts = stretch.cache_counts

function stretch.pool_state()
    local drawn, idle, waitingNow = 0, 0, 0
    for _, rec in pairs(slots) do
        if rec.refs > 0 then drawn = drawn + 1 else idle = idle + 1 end
    end
    for _ in pairs(waiting) do waitingNow = waitingNow + 1 end
    return { drawn = drawn, idle = idle, waiting = waitingNow, evicted = stretch.evicted,
             overflow = stretch.overCap, refused = stretch.refused }
end

function stretch.free_unused()
    local drop, dropv = bound("gfx_delete"), bound("vtx_delete")
    local freed, freedv = 0, 0
    for n, rec in pairs(slots) do
        if rec.refs <= 0 then
            forget_list(n)
            if drop ~= nil and rec.gfx ~= nil then drop(rec.gfx) end
            slots[n] = nil
            table.insert(freeLists, n)
            freed = freed + 1
        end
    end
    for b, rec in pairs(bslots) do
        if rec.users <= 0 then
            forget_buffer(b)
            if dropv ~= nil and rec.vtx ~= nil then dropv(rec.vtx) end
            bslots[b] = nil
            table.insert(freeBuffers, b)
            freedv = freedv + 1
        end
    end
    table.sort(freeLists, function(a, b) return a > b end)
    table.sort(freeBuffers, function(a, b) return a > b end)
    return freed, freedv
end
stretch.free_all = stretch.free_unused

function stretch.solid(o, pieces)
    local handles = {}
    if o == nil then return handles end
    local build_solid, scale_xyz = bound("load_static_object_collision"), bound("obj_scale_xyz")
    if build_solid == nil or scale_xyz == nil then return handles end
    local build = bound("obj_build_transform_from_pos_and_angle")
    local x, y, z = o.oPosX, o.oPosY, o.oPosZ
    local q = math.floor(((tonumber(o.oFaceAngleYaw) or 0) % 0x10000) / 0x4000 + 0.5) % 4
    local c = ({ 1, 0, -1, 0 })[q + 1]
    local s = ({ 0, 1, 0, -1 })[q + 1]
    local keep = o.collisionData
    for _, p in ipairs(pieces) do
        if p.mesh ~= nil then
            o.collisionData = p.mesh
            local ox, oz = p.ox or 0, p.oz or 0
            o.oPosX = x + ox * c + oz * s
            o.oPosZ = z - ox * s + oz * c
            o.oPosY = y + (p.oy or 0)
            if build ~= nil then build(o, 0x06, 0x12) end
            scale_xyz(o, p.sx, p.sy, p.sz)
            local handle = build_solid()
            if handle ~= nil then handles[#handles + 1] = handle end
        end
    end
    o.oPosX, o.oPosY, o.oPosZ = x, y, z
    if build ~= nil then build(o, 0x06, 0x12) end
    o.collisionData = keep or (pieces[1] ~= nil and pieces[1].mesh) or nil
    if bound("obj_scale") ~= nil then obj_scale(o, 1) end
    return handles
end

function stretch.solid_pieces(params, shapeMesh, crate, fitShape, fitCrate)
    local byte, texture, w, h, d = stretch.shape_decode(params)
    fitShape, fitCrate = fitShape or 1, fitCrate or 1

    if stretch.is_prop(byte) then
        local rid = stretch.prop_decode(params)
        local r = stretch.RECIPES ~= nil and stretch.RECIPES[rid] or nil
        local cell = stretch.CELL
        if r ~= nil and r.boxes ~= nil then
            local out = {}
            for _, b in ipairs(r.boxes) do
                out[#out + 1] = { mesh = crate, sx = (b[2] - b[1]) / cell * fitCrate,
                    sy = (b[4] - b[3]) / cell * fitCrate, sz = (b[6] - b[5]) / cell * fitCrate,
                    ox = (b[1] + b[2]) / 2, oy = b[3], oz = (b[5] + b[6]) / 2 }
            end
            return out
        end
        if r == nil or r.solid == nil then return {} end
        return { { mesh = crate, sx = r.solid[1] / cell * fitCrate,
                   sy = r.solid[2] / cell * fitCrate, sz = r.solid[3] / cell * fitCrate } }
    end
    if stretch.JOIN_BYTES[byte] == nil then
        w, h, d = stretch.cells_of(byte, w, h, d)
        return { { mesh = shapeMesh, sx = w * fitShape, sy = h * fitShape, sz = d * fitShape } }
    end
    local J = stretch.JOIN_SIZES
    local _, _, _, _, codes = stretch.join_decode(params)
    local out = {}
    local cell = J.cell
    if byte == stretch.JOIN_PILLAR then
        out[1] = { mesh = shapeMesh, sx = fitShape, sy = fitShape, sz = fitShape }
    else
        out[1] = { mesh = crate, sx = J.fence / cell * fitCrate,
                   sy = J.fence_high / cell * fitCrate, sz = J.fence / cell * fitCrate }
    end
    local thick = byte == stretch.JOIN_PILLAR and J.wall or J.fence
    local high = byte == stretch.JOIN_PILLAR and J.top or J.fence_high
    local from = byte == stretch.JOIN_PILLAR and (J.pillar - J.wall) or J.fence / 2
    for k = 1, 4 do
        local code = codes[k] or 0
        if code > 0 then
            local to = stretch.join_reach(byte == stretch.JOIN_PILLAR and 1 or code)
            local mid, len = (from + to) / 2, to - from
            local ox = (k == 1 and mid) or (k == 3 and -mid) or 0
            local oz = (k == 2 and mid) or (k == 4 and -mid) or 0
            local along = k == 1 or k == 3
            out[#out + 1] = { mesh = crate,
                sx = (along and len or thick) / cell * fitCrate, sy = high / cell * fitCrate,
                sz = (along and thick or len) / cell * fitCrate, ox = ox, oz = oz }
        end
    end
    return out
end

function stretch.relight_step()
    local done = 0
    local shade = nil
    for b = 1, highBuffer do
        local rec = bslots[b]
        if rec ~= nil and rec.baked ~= nil and rec.vtx ~= nil and rec.sunAt ~= stretch.sunSerial then
            if done >= stretch.RELIGHT_VERTICES then break end
            if shade == nil then
                shade = type(stretch.relit) == "function" and stretch.relit(stretch.sun) or false
            end
            local at = rec.vtx
            for _, v in ipairs(rec.baked) do
                if at == nil then break end
                if shade and v[13] ~= nil then
                    at.r, at.g, at.b = shade(v[6], v[7], v[8], v[13], v[14])
                else
                    at.r, at.g, at.b = v[9], v[10], v[11]
                end
                at = vtx_get_next_vertex(at)
            end
            rec.sunAt = stretch.sunSerial
            done = done + #rec.baked
        end
    end
    return done
end

function stretch.on_unload(o)
    if o == nil then return end
    if objSlot[o] ~= nil or byObject[o] ~= nil then stretch.release(o) end
end

function stretch.level_reset()
    local drew = {}
    for o in pairs(objSlot) do drew[#drew + 1] = o end
    for o in pairs(byObject) do if objSlot[o] == nil then drew[#drew + 1] = o end end
    for _, o in ipairs(drew) do stretch.release(o) end
    byObject, objSlot, waiting, objKey = {}, {}, {}, {}
    return #drew
end

hook_event(HOOK_ON_OBJECT_UNLOAD, stretch.on_unload)
if HOOK_UPDATE ~= nil then hook_event(HOOK_UPDATE, stretch.relight_step) end
if HOOK_ON_LEVEL_INIT ~= nil then hook_event(HOOK_ON_LEVEL_INIT, stretch.level_reset) end

function stretch.lua_restarted()
    slots, listOf, bslots, bufOf = {}, {}, {}, {}
    highList, highBuffer, freeLists, freeBuffers, tick = 0, 0, {}, {}, 0
    byObject, objSlot, waiting, objKey = {}, {}, {}, {}
    merged, mergedSerial, mergedCount = {}, 0, {}
    template, shapeTemplate = nil, nil
    lastNode, display, shapeNode, shapeDisplay = nil, nil, nil, nil
    stretch.overCap, stretch.evicted, stretch.refused = 0, 0, 0
    stretch.lastKey = nil
end
